INSERT INTO public.topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status)
VALUES ('40300000-0000-0000-0000-000000000001', '40200000-0000-0000-0000-000000000001', 1, 'que-es-el-dinero', $j${"en-US":"What Is Money?","es-MX":"¿Qué es el dinero?","pt-BR":"O que é dinheiro?"}$j$::jsonb, $t$El dinero es cualquier cosa que un grupo de personas acepta a cambio de bienes o servicios. Antes de las monedas, la gente intercambiaba directamente lo que tenía (trueque).$t$, $j${"en-US":"Understand what money is and why it exists","es-MX":"Comprender qué es el dinero y por qué existe","pt-BR":"Compreender o que é dinheiro e por que existe"}$j$::jsonb, $j$["dinero","intercambiar","trueque","vendedor"]$j$::jsonb, $t$Sabe contar objetos y reconocer que las cosas tienen dueño.$t$, 'published')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status)
VALUES ('40300000-0000-0000-0000-000000000002', '40200000-0000-0000-0000-000000000001', 2, 'el-trueque', $j${"en-US":"Bartering","es-MX":"El trueque","pt-BR":"A troca"}$j$::jsonb, $t$El trueque es cambiar una cosa por otra sin usar dinero. Funciona solo cuando ambas personas quieren lo que la otra ofrece.$t$, $j${"en-US":"Recognize when bartering works and when it fails","es-MX":"Reconocer cuándo el trueque funciona y cuándo falla","pt-BR":"Reconhecer quando a troca funciona e quando falha"}$j$::jsonb, $j$["trueque","cambio justo","necesitar"]$j$::jsonb, $t$Entiende el concepto básico de intercambiar cosas.$t$, 'published')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status)
VALUES ('40300000-0000-0000-0000-000000000003', '40200000-0000-0000-0000-000000000002', 1, 'monedas-y-billetes', $j${"en-US":"Coins and Bills","es-MX":"Monedas y billetes","pt-BR":"Moedas e notas"}$j$::jsonb, $t$Las monedas y billetes son formas de dinero que la comunidad acepta como pago, porque todos confían en su valor.$t$, $j${"en-US":"Understand where coins come from and why communities trust them","es-MX":"Comprender de dónde vienen las monedas y por qué la comunidad confía en ellas","pt-BR":"Compreender de onde vêm as moedas e por que a comunidade confia nelas"}$j$::jsonb, $j$["moneda","confianza","alcancía"]$j$::jsonb, $t$Sabe qué es el trueque y por qué a veces falla.$t$, 'published')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.topics (id, saga_id, position, slug, title, concept_md, learning_objective, key_vocabulary, prior_knowledge, status)
VALUES ('40300000-0000-0000-0000-000000000004', '40200000-0000-0000-0000-000000000002', 2, 'para-que-sirve-el-dinero', $j${"en-US":"What Money Is For","es-MX":"Para qué sirve el dinero","pt-BR":"Para que serve o dinheiro"}$j$::jsonb, $t$El dinero sirve para comprar lo que necesitas y también para ahorrar y usarlo después.$t$, $j${"en-US":"Understand buying and saving as two uses of money","es-MX":"Comprender comprar y ahorrar como dos usos del dinero","pt-BR":"Compreender comprar e poupar como dois usos do dinheiro"}$j$::jsonb, $j$["comprar","ahorrar","alcancía","meta"]$j$::jsonb, $t$Sabe qué son las monedas y por qué son útiles.$t$, 'published')
ON CONFLICT (id) DO NOTHING;

