INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000001', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"el-deseo-de-dino","title":"Dino's Wish","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["Understand that you need to offer something to get something that belongs to someone else"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"el-deseo-de-dino-scene","type":"story_scene","prompt_md":"The wish begins","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"excited"},"payload":{"backdrop":"band","character":"dino","emotion":"excited","action":"point","body_md":"Dino sees a toy boat at the market stall. **He wants it so much!** But when he checks his pockets… he has nothing to offer the seller in exchange.","art":{"icon":"sailing","tint":"accent"}}},{"id":"el-deseo-de-dino-quiz","type":"quiz_mcq","prompt_md":"What does Dino need to take the boat home?","difficulty":1,"xp":10,"hints":["Think about what the seller might need."],"explanation_md":"To take home something that isn't yours, you need to give something in return: that's exchanging.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Something the seller wants in return"},{"id":"b","text_md":"Yell really loud until it's given to him for free","rationale_md":"Yelling doesn't get you anything — that isn't exchanging."},{"id":"c","text_md":"Wait for the boat to become free on its own","rationale_md":"Things don't become free on their own."}]}},{"id":"el-deseo-de-dino-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"Even if you want something a lot, if it belongs to someone else, you need to offer something in exchange.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Dino can take the boat home for free, just because he wants it a lot.","justifications":[{"id":"j1","text_md":"True, wanting something a lot is enough to have it."},{"id":"j2","text_md":"False, everything someone sells belongs to them and needs something in exchange."},{"id":"j3","text_md":"False, because toy boats can't be sold."}]}},{"id":"el-deseo-de-dino-pic","type":"picture_choice","prompt_md":"What could Dino offer the seller in exchange for the boat?","difficulty":1,"xp":20,"explanation_md":"Offering something useful that's yours, like fresh fish, is a fair exchange.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"set_meal","label":"Fresh fish he caught today"},{"id":"b","icon":"toys","label":"His own broken toy boat","rationale_md":"Something broken isn't worth the same to the seller."},{"id":"c","icon":"cloud","label":"A pretty cloud","rationale_md":"You can't give away something you don't own or can't hand over."}]}}]}$j$::jsonb, $j${"el-deseo-de-dino-quiz":{"correct_option_id":"a"},"el-deseo-de-dino-tf":{"is_true":false,"correct_justification_id":"j2"},"el-deseo-de-dino-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000001', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"el-deseo-de-dino","title":"El deseo de Dino","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Comprender que necesitas ofrecer algo para obtener algo que es de alguien más"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"el-deseo-de-dino-scene","type":"story_scene","prompt_md":"Nace un deseo","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"excited"},"payload":{"backdrop":"band","character":"dino","emotion":"excited","action":"point","body_md":"Dino ve un barquito de juguete en un puesto del mercado. **¡Lo quiere mucho!** Pero cuando busca en sus bolsillos… no tiene nada para dárselo al vendedor a cambio.","art":{"icon":"sailing","tint":"accent"}}},{"id":"el-deseo-de-dino-quiz","type":"quiz_mcq","prompt_md":"¿Qué necesita Dino para poder llevarse el barquito?","difficulty":1,"xp":10,"hints":["Piensa en lo que el vendedor podría necesitar."],"explanation_md":"Para llevarte algo que no es tuyo, necesitas dar algo a cambio: eso es intercambiar.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Algo que el vendedor quiera a cambio"},{"id":"b","text_md":"Gritar muy fuerte hasta que se lo regalen","rationale_md":"Gritar no consigue nada, eso no es intercambiar."},{"id":"c","text_md":"Esperar a que el barquito se vuelva gratis","rationale_md":"Las cosas no se vuelven gratis solas."}]}},{"id":"el-deseo-de-dino-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"Aunque quieras algo mucho, si es de alguien más, necesitas ofrecer algo a cambio.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Dino puede llevarse el barquito sin dar nada a cambio, solo porque lo quiere mucho.","justifications":[{"id":"j1","text_md":"Cierto, querer algo mucho es suficiente para tenerlo."},{"id":"j2","text_md":"Falso, todo lo que alguien vende tiene un dueño y hay que dar algo a cambio."},{"id":"j3","text_md":"Falso, porque los barquitos de juguete no se pueden vender."}]}},{"id":"el-deseo-de-dino-pic","type":"picture_choice","prompt_md":"¿Qué podría ofrecerle Dino al vendedor a cambio del barquito?","difficulty":1,"xp":20,"explanation_md":"Ofrecer algo útil y tuyo, como pescados frescos, es un buen intercambio.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"set_meal","label":"Pescados frescos que atrapó hoy"},{"id":"b","icon":"toys","label":"Su propio barquito roto","rationale_md":"Algo roto no tiene el mismo valor para el vendedor."},{"id":"c","icon":"cloud","label":"Una nube bonita","rationale_md":"No puedes dar algo que no es tuyo ni se puede entregar."}]}}]}$j$::jsonb, $j${"el-deseo-de-dino-quiz":{"correct_option_id":"a"},"el-deseo-de-dino-tf":{"is_true":false,"correct_justification_id":"j2"},"el-deseo-de-dino-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000001', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"el-deseo-de-dino","title":"O desejo de Dino","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Compreender que você precisa oferecer algo para conseguir algo que é de outra pessoa"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"el-deseo-de-dino-scene","type":"story_scene","prompt_md":"Nasce um desejo","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"excited"},"payload":{"backdrop":"band","character":"dino","emotion":"excited","action":"point","body_md":"Dino vê um barquinho de brinquedo na barraca do mercado. **Ele quer muito!** Mas quando procura nos bolsos… não tem nada para oferecer ao vendedor em troca.","art":{"icon":"sailing","tint":"accent"}}},{"id":"el-deseo-de-dino-quiz","type":"quiz_mcq","prompt_md":"O que Dino precisa para levar o barquinho?","difficulty":1,"xp":10,"hints":["Pense no que o vendedor pode precisar."],"explanation_md":"Para levar algo que não é seu, você precisa dar algo em troca: isso é trocar.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Algo que o vendedor queira em troca"},{"id":"b","text_md":"Gritar bem alto até ganhá-lo de graça","rationale_md":"Gritar não consegue nada — isso não é trocar."},{"id":"c","text_md":"Esperar o barquinho ficar grátis sozinho","rationale_md":"As coisas não ficam grátis sozinhas."}]}},{"id":"el-deseo-de-dino-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"Mesmo que você queira muito algo, se é de outra pessoa, precisa oferecer algo em troca.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Dino pode levar o barquinho de graça, só porque quer muito.","justifications":[{"id":"j1","text_md":"Verdade, querer muito algo é suficiente para tê-lo."},{"id":"j2","text_md":"Falso, tudo que alguém vende tem um dono e é preciso dar algo em troca."},{"id":"j3","text_md":"Falso, porque barquinhos de brinquedo não podem ser vendidos."}]}},{"id":"el-deseo-de-dino-pic","type":"picture_choice","prompt_md":"O que Dino poderia oferecer ao vendedor em troca do barquinho?","difficulty":1,"xp":20,"explanation_md":"Oferecer algo útil e seu, como peixes frescos, é uma boa troca.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"set_meal","label":"Peixes frescos que pegou hoje"},{"id":"b","icon":"toys","label":"Seu próprio barquinho quebrado","rationale_md":"Algo quebrado não tem o mesmo valor para o vendedor."},{"id":"c","icon":"cloud","label":"Uma nuvem bonita","rationale_md":"Você não pode dar algo que não é seu nem pode entregar."}]}}]}$j$::jsonb, $j${"el-deseo-de-dino-quiz":{"correct_option_id":"a"},"el-deseo-de-dino-tf":{"is_true":false,"correct_justification_id":"j2"},"el-deseo-de-dino-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

