INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000002', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"el-problema-del-trueque","title":"The Trouble with Bartering","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["Recognize that bartering fails when the other side doesn't want what you offer"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"el-problema-del-trueque-scene","type":"story_scene","prompt_md":"A new problem","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"thinking"},"payload":{"backdrop":"band","character":"dino","emotion":"thinking","action":"think","body_md":"Dino offers his fish to the seller, but the seller already has plenty of fish and **doesn't need any more**. Dino scratches his head: now what?","art":{"icon":"help","tint":"accent"}}},{"id":"el-problema-del-trueque-quiz","type":"quiz_mcq","prompt_md":"What is Dino's problem?","difficulty":1,"xp":10,"hints":["Notice what the seller already has."],"explanation_md":"To exchange, both people need to want what the other offers. If it doesn't match, bartering fails.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"The seller doesn't want what Dino has to offer"},{"id":"b","text_md":"Dino has no fish","rationale_md":"He does have fish — that's not the problem."},{"id":"c","text_md":"The boat no longer exists","rationale_md":"The boat is still there, waiting."}]}},{"id":"el-problema-del-trueque-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"Bartering needs both sides to want what the other has — that doesn't always happen.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Bartering always works, no matter what each person has.","justifications":[{"id":"j1","text_md":"True, anything can be traded for anything."},{"id":"j2","text_md":"False, bartering only works if both people want what the other offers."},{"id":"j3","text_md":"False, because bartering is forbidden in the archipelago."}]}},{"id":"el-problema-del-trueque-pic","type":"picture_choice","prompt_md":"What could help Dino avoid this problem in the future?","difficulty":1,"xp":20,"explanation_md":"Something everyone accepts — like coins — solves the problem that bartering doesn't always match up.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Something EVERYONE accepts, like coins"},{"id":"b","icon":"block","label":"Give up and never trade again","rationale_md":"Giving up doesn't solve the problem."},{"id":"c","icon":"shuffle","label":"Move to another island forever","rationale_md":"Moving away doesn't solve how to exchange things."}]}}]}$j$::jsonb, $j${"el-problema-del-trueque-quiz":{"correct_option_id":"a"},"el-problema-del-trueque-tf":{"is_true":false,"correct_justification_id":"j2"},"el-problema-del-trueque-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000002', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"el-problema-del-trueque","title":"El problema del trueque","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Reconocer que el trueque falla cuando la otra parte no quiere lo que ofreces"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"el-problema-del-trueque-scene","type":"story_scene","prompt_md":"Un nuevo problema","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"thinking"},"payload":{"backdrop":"band","character":"dino","emotion":"thinking","action":"think","body_md":"Dino ofrece sus pescados al vendedor, pero el vendedor ya tiene muchos pescados y **no los necesita**. Dino se rasca la cabeza: ¿ahora qué hace?","art":{"icon":"help","tint":"accent"}}},{"id":"el-problema-del-trueque-quiz","type":"quiz_mcq","prompt_md":"¿Cuál es el problema de Dino?","difficulty":1,"xp":10,"hints":["Fíjate en qué es lo que el vendedor YA tiene."],"explanation_md":"Para intercambiar, las dos personas deben querer lo que la otra ofrece. Si no coincide, el trueque falla.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"El vendedor no quiere lo que Dino tiene para ofrecer"},{"id":"b","text_md":"Dino no tiene pescados","rationale_md":"Sí tiene pescados, ese no es el problema."},{"id":"c","text_md":"El barquito ya no existe","rationale_md":"El barquito sigue ahí, esperando."}]}},{"id":"el-problema-del-trueque-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"El trueque necesita que las dos partes quieran lo que la otra tiene, eso no siempre pasa.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"El trueque siempre funciona, sin importar lo que cada quien tenga.","justifications":[{"id":"j1","text_md":"Cierto, cualquier cosa se puede cambiar por cualquier cosa."},{"id":"j2","text_md":"Falso, el trueque solo funciona si ambas personas quieren lo que la otra ofrece."},{"id":"j3","text_md":"Falso, porque el trueque está prohibido en el archipiélago."}]}},{"id":"el-problema-del-trueque-pic","type":"picture_choice","prompt_md":"¿Qué podría ayudar a Dino a resolver este problema en el futuro?","difficulty":1,"xp":20,"explanation_md":"Algo que todos acepten, como las monedas, resuelve el problema de que el trueque no siempre coincide.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Algo que TODOS acepten, como monedas"},{"id":"b","icon":"block","label":"Rendirse y no volver a intercambiar nada","rationale_md":"Rendirse no resuelve el problema."},{"id":"c","icon":"shuffle","label":"Cambiar de isla para siempre","rationale_md":"Mudarse no resuelve cómo intercambiar cosas."}]}}]}$j$::jsonb, $j${"el-problema-del-trueque-quiz":{"correct_option_id":"a"},"el-problema-del-trueque-tf":{"is_true":false,"correct_justification_id":"j2"},"el-problema-del-trueque-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000002', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"el-problema-del-trueque","title":"O problema da troca","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Reconhecer que a troca falha quando o outro lado não quer o que você oferece"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"el-problema-del-trueque-scene","type":"story_scene","prompt_md":"Um novo problema","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"thinking"},"payload":{"backdrop":"band","character":"dino","emotion":"thinking","action":"think","body_md":"Dino oferece seus peixes ao vendedor, mas o vendedor já tem muitos peixes e **não precisa de mais**. Dino coça a cabeça: e agora?","art":{"icon":"help","tint":"accent"}}},{"id":"el-problema-del-trueque-quiz","type":"quiz_mcq","prompt_md":"Qual é o problema de Dino?","difficulty":1,"xp":10,"hints":["Repare no que o vendedor JÁ tem."],"explanation_md":"Para trocar, as duas pessoas precisam querer o que a outra oferece. Se não combinar, a troca falha.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"O vendedor não quer o que Dino tem para oferecer"},{"id":"b","text_md":"Dino não tem peixes","rationale_md":"Ele tem peixes sim, esse não é o problema."},{"id":"c","text_md":"O barquinho não existe mais","rationale_md":"O barquinho ainda está lá, esperando."}]}},{"id":"el-problema-del-trueque-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"A troca precisa que os dois lados queiram o que o outro tem, isso nem sempre acontece.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"A troca sempre funciona, não importa o que cada um tenha.","justifications":[{"id":"j1","text_md":"Verdade, qualquer coisa pode ser trocada por qualquer coisa."},{"id":"j2","text_md":"Falso, a troca só funciona se as duas pessoas quiserem o que a outra oferece."},{"id":"j3","text_md":"Falso, porque a troca é proibida no arquipélago."}]}},{"id":"el-problema-del-trueque-pic","type":"picture_choice","prompt_md":"O que poderia ajudar Dino a evitar esse problema no futuro?","difficulty":1,"xp":20,"explanation_md":"Algo que todos aceitem, como moedas, resolve o problema de a troca nem sempre combinar.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Algo que TODOS aceitem, como moedas"},{"id":"b","icon":"block","label":"Desistir e nunca mais trocar nada","rationale_md":"Desistir não resolve o problema."},{"id":"c","icon":"shuffle","label":"Mudar de ilha para sempre","rationale_md":"Mudar de lugar não resolve como trocar coisas."}]}}]}$j$::jsonb, $j${"el-problema-del-trueque-quiz":{"correct_option_id":"a"},"el-problema-del-trueque-tf":{"is_true":false,"correct_justification_id":"j2"},"el-problema-del-trueque-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

