VALUES ('40400000-0000-0000-0000-000000000003', '40300000-0000-0000-0000-000000000002', 1, 'cambiar-cosas-por-cosas', $j${"en-US":"Trading Things for Things","es-MX":"Cambiar cosas por cosas","pt-BR":"Trocar coisas por coisas"}$j$::jsonb, 1, 40, 5, $j$["dina","dino"]$j$::jsonb, 'published')
