INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000003', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"cambiar-cosas-por-cosas","title":"Trading Things for Things","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["See a fair barter where both sides receive something they need"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cambiar-cosas-por-cosas-scene","type":"story_scene","prompt_md":"A fair trade","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"happy"},"payload":{"backdrop":"band","character":"dina","emotion":"happy","action":"wave","body_md":"Dina has extra coconuts. Dino has extra fish. **They trade coconuts for fish!** Both go home happy with something they needed.","art":{"icon":"swap_horiz","tint":"success"}}},{"id":"cambiar-cosas-por-cosas-quiz","type":"quiz_mcq","prompt_md":"Why were Dina and Dino both happy with the trade?","difficulty":1,"xp":10,"hints":["Think about what each one had extra of."],"explanation_md":"Bartering works well when both people really want what the other offers.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Because each one received something they truly needed"},{"id":"b","text_md":"Because nobody paid anything","rationale_md":"They did \"pay\" with what they had — just not with money."},{"id":"c","text_md":"Because coconuts are worth more than fish","rationale_md":"Bartering isn't about which is worth more, but about both sides wanting the trade."}]}},{"id":"cambiar-cosas-por-cosas-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"A fair barter works when both people end up happy with what they receive.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"In a good barter, both people receive something they want.","justifications":[{"id":"j1","text_md":"True, that's why both sides agree to the trade."},{"id":"j2","text_md":"False, only one person should come out ahead."},{"id":"j3","text_md":"False, bartering is always unfair."}]}},{"id":"cambiar-cosas-por-cosas-pic","type":"picture_choice","prompt_md":"Which of these is an example of a good barter?","difficulty":1,"xp":20,"explanation_md":"A real barter is a fair exchange both sides agree to.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"agriculture","label":"Trading corn for eggs, if both sides want to"},{"id":"b","icon":"sentiment_dissatisfied","label":"Taking something from someone without giving anything","rationale_md":"That isn't a barter, it's taking something without permission."},{"id":"c","icon":"question_mark","label":"Promising something and not delivering it","rationale_md":"A real barter is completed right away with what was promised."}]}}]}$j$::jsonb, $j${"cambiar-cosas-por-cosas-quiz":{"correct_option_id":"a"},"cambiar-cosas-por-cosas-tf":{"is_true":true,"correct_justification_id":"j1"},"cambiar-cosas-por-cosas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000003', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"cambiar-cosas-por-cosas","title":"Cambiar cosas por cosas","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Ver un trueque justo donde ambas partes reciben algo que necesitan"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cambiar-cosas-por-cosas-scene","type":"story_scene","prompt_md":"Un cambio justo","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"happy"},"payload":{"backdrop":"band","character":"dina","emotion":"happy","action":"wave","body_md":"Dina tiene cocos de sobra. Dino tiene pescados de sobra. **¡Cambian cocos por pescados!** Los dos se van felices con algo que necesitaban.","art":{"icon":"swap_horiz","tint":"success"}}},{"id":"cambiar-cosas-por-cosas-quiz","type":"quiz_mcq","prompt_md":"¿Por qué Dina y Dino quedaron contentos con el cambio?","difficulty":1,"xp":10,"hints":["Piensa en qué tenía de sobra cada uno."],"explanation_md":"El trueque funciona bien cuando las dos personas realmente quieren lo que la otra ofrece.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Porque cada quien recibió algo que sí necesitaba"},{"id":"b","text_md":"Porque nadie pagó nada","rationale_md":"Sí \"pagaron\" con lo que tenían, solo que no era dinero."},{"id":"c","text_md":"Porque los cocos valen más que los pescados","rationale_md":"En el trueque no se trata de cuál vale más, sino de que ambos quieran el cambio."}]}},{"id":"cambiar-cosas-por-cosas-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"Un trueque justo funciona cuando ambas personas quedan contentas con lo que reciben.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"En un buen trueque, las dos personas reciben algo que quieren.","justifications":[{"id":"j1","text_md":"Cierto, por eso ambas partes aceptan el cambio."},{"id":"j2","text_md":"Falso, solo una persona debe salir ganando."},{"id":"j3","text_md":"Falso, el trueque siempre es injusto."}]}},{"id":"cambiar-cosas-por-cosas-pic","type":"picture_choice","prompt_md":"¿Cuál de estos es un ejemplo de buen trueque?","difficulty":1,"xp":20,"explanation_md":"Un trueque real es un cambio justo donde ambas partes están de acuerdo.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"agriculture","label":"Cambiar maíz por huevos, si ambos lo quieren"},{"id":"b","icon":"sentiment_dissatisfied","label":"Quitarle algo a alguien sin dar nada","rationale_md":"Eso no es un trueque, es quitar algo sin permiso."},{"id":"c","icon":"question_mark","label":"Prometer algo y no cumplir","rationale_md":"Un trueque real se cumple de inmediato con lo prometido."}]}}]}$j$::jsonb, $j${"cambiar-cosas-por-cosas-quiz":{"correct_option_id":"a"},"cambiar-cosas-por-cosas-tf":{"is_true":true,"correct_justification_id":"j1"},"cambiar-cosas-por-cosas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000003', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"cambiar-cosas-por-cosas","title":"Trocar coisas por coisas","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Ver uma troca justa em que os dois lados recebem algo que precisam"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cambiar-cosas-por-cosas-scene","type":"story_scene","prompt_md":"Uma troca justa","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"happy"},"payload":{"backdrop":"band","character":"dina","emotion":"happy","action":"wave","body_md":"Dina tem cocos sobrando. Dino tem peixes sobrando. **Eles trocam cocos por peixes!** Os dois vão embora felizes com algo que precisavam.","art":{"icon":"swap_horiz","tint":"success"}}},{"id":"cambiar-cosas-por-cosas-quiz","type":"quiz_mcq","prompt_md":"Por que Dina e Dino ficaram contentes com a troca?","difficulty":1,"xp":10,"hints":["Pense no que cada um tinha de sobra."],"explanation_md":"A troca funciona bem quando as duas pessoas realmente querem o que a outra oferece.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Porque cada um recebeu algo que realmente precisava"},{"id":"b","text_md":"Porque ninguém pagou nada","rationale_md":"Eles \"pagaram\" com o que tinham, só que não era dinheiro."},{"id":"c","text_md":"Porque os cocos valem mais que os peixes","rationale_md":"Na troca não importa qual vale mais, e sim que os dois queiram trocar."}]}},{"id":"cambiar-cosas-por-cosas-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"Uma troca justa funciona quando as duas pessoas ficam contentes com o que recebem.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Numa boa troca, as duas pessoas recebem algo que querem.","justifications":[{"id":"j1","text_md":"Verdade, por isso os dois lados aceitam a troca."},{"id":"j2","text_md":"Falso, só uma pessoa deve sair ganhando."},{"id":"j3","text_md":"Falso, a troca é sempre injusta."}]}},{"id":"cambiar-cosas-por-cosas-pic","type":"picture_choice","prompt_md":"Qual destes é um exemplo de boa troca?","difficulty":1,"xp":20,"explanation_md":"Uma troca de verdade é uma troca justa em que os dois lados concordam.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"agriculture","label":"Trocar milho por ovos, se os dois quiserem"},{"id":"b","icon":"sentiment_dissatisfied","label":"Tirar algo de alguém sem dar nada","rationale_md":"Isso não é uma troca, é tirar algo sem permissão."},{"id":"c","icon":"question_mark","label":"Prometer algo e não cumprir","rationale_md":"Uma troca de verdade se cumpre logo com o que foi prometido."}]}}]}$j$::jsonb, $j${"cambiar-cosas-por-cosas-quiz":{"correct_option_id":"a"},"cambiar-cosas-por-cosas-tf":{"is_true":true,"correct_justification_id":"j1"},"cambiar-cosas-por-cosas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lessons (id, topic_id, position, slug, title, difficulty, xp_total, estimated_minutes, "cast", status)
VALUES ('40400000-0000-0000-0000-000000000004', '40300000-0000-0000-0000-000000000002', 2, 'cuando-el-trueque-falla', $j${"en-US":"When Bartering Fails","es-MX":"Cuando el trueque falla","pt-BR":"Quando a troca falha"}$j$::jsonb, 1, 40, 5, $j$["dina","dino"]$j$::jsonb, 'published')
