INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000004', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"cuando-el-trueque-falla","title":"When Bartering Fails","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["Understand that what people need can change over time"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cuando-el-trueque-falla-scene","type":"story_scene","prompt_md":"Not this time","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"neutral"},"payload":{"backdrop":"band","character":"dina","emotion":"neutral","action":"shake","body_md":"The next week, Dino comes back with more fish… but Dina **already has plenty** of coconuts and doesn't want more fish. This time, last week's barter doesn't work.","art":{"icon":"sentiment_neutral","tint":"warning"}}},{"id":"cuando-el-trueque-falla-quiz","type":"quiz_mcq","prompt_md":"What happened this time with Dino and Dina's barter?","difficulty":1,"xp":10,"hints":["What did Dina say about the coconuts?"],"explanation_md":"Bartering depends on both people wanting the trade RIGHT NOW — and that can change.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Dina no longer wanted what Dino was offering"},{"id":"b","text_md":"Dino no longer had fish","rationale_md":"He did have fish — that wasn't the problem."},{"id":"c","text_md":"The coconuts disappeared","rationale_md":"The coconuts are still there — the problem is something else."}]}},{"id":"cuando-el-trueque-falla-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"What people need changes over time. That's why bartering doesn't always work the same way.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Bartering always works the same way, every week.","justifications":[{"id":"j1","text_md":"True, what worked once always works again."},{"id":"j2","text_md":"False, what someone needs can change over time."},{"id":"j3","text_md":"False, because bartering can only be done once in a lifetime."}]}},{"id":"cuando-el-trueque-falla-pic","type":"picture_choice","prompt_md":"What would help Dino more in the future?","difficulty":1,"xp":20,"explanation_md":"Having something almost everyone always accepts — like coins — avoids the problem of bartering not matching up.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Something almost everyone always accepts, like coins"},{"id":"b","icon":"redo","label":"Offer the same fish again and again","rationale_md":"That doesn't fix the fact that they aren't wanted anymore."},{"id":"c","icon":"sentiment_very_dissatisfied","label":"Stop trading forever","rationale_md":"Giving up doesn't solve the problem."}]}}]}$j$::jsonb, $j${"cuando-el-trueque-falla-quiz":{"correct_option_id":"a"},"cuando-el-trueque-falla-tf":{"is_true":false,"correct_justification_id":"j2"},"cuando-el-trueque-falla-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000004', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"cuando-el-trueque-falla","title":"Cuando el trueque falla","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Comprender que lo que las personas necesitan puede cambiar con el tiempo"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cuando-el-trueque-falla-scene","type":"story_scene","prompt_md":"Esta vez no","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"neutral"},"payload":{"backdrop":"band","character":"dina","emotion":"neutral","action":"shake","body_md":"La próxima semana, Dino vuelve con más pescados… pero Dina **ya tiene demasiados** cocos y no quiere más pescado. El trueque de la semana pasada, esta vez, no funciona.","art":{"icon":"sentiment_neutral","tint":"warning"}}},{"id":"cuando-el-trueque-falla-quiz","type":"quiz_mcq","prompt_md":"¿Qué pasó esta vez con el trueque de Dino y Dina?","difficulty":1,"xp":10,"hints":["¿Qué dijo Dina sobre los cocos?"],"explanation_md":"El trueque depende de que ambas personas quieran el cambio EN ESE MOMENTO, y eso puede cambiar.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Dina ya no quería lo que Dino ofrecía"},{"id":"b","text_md":"Dino ya no tenía pescados","rationale_md":"Sí tenía, ese no era el problema."},{"id":"c","text_md":"Los cocos desaparecieron","rationale_md":"Los cocos siguen ahí, el problema es otro."}]}},{"id":"cuando-el-trueque-falla-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"Lo que las personas necesitan cambia. Por eso el trueque no siempre funciona igual.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"El trueque siempre funciona igual, todas las semanas.","justifications":[{"id":"j1","text_md":"Cierto, lo que funcionó una vez funciona siempre."},{"id":"j2","text_md":"Falso, lo que alguien necesita puede cambiar con el tiempo."},{"id":"j3","text_md":"Falso, porque el trueque solo se puede hacer una vez en la vida."}]}},{"id":"cuando-el-trueque-falla-pic","type":"picture_choice","prompt_md":"¿Qué le convendría más a Dino en el futuro?","difficulty":1,"xp":20,"explanation_md":"Tener algo que casi todos aceptan siempre, como las monedas, evita el problema de que el trueque no siempre coincide.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Tener algo que casi todos aceptan siempre, como monedas"},{"id":"b","icon":"redo","label":"Ofrecer los mismos pescados una y otra vez","rationale_md":"Eso no resuelve que ya no los quieran."},{"id":"c","icon":"sentiment_very_dissatisfied","label":"Dejar de intercambiar para siempre","rationale_md":"Rendirse no soluciona el problema."}]}}]}$j$::jsonb, $j${"cuando-el-trueque-falla-quiz":{"correct_option_id":"a"},"cuando-el-trueque-falla-tf":{"is_true":false,"correct_justification_id":"j2"},"cuando-el-trueque-falla-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000004', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"cuando-el-trueque-falla","title":"Quando a troca falha","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Compreender que o que as pessoas precisam pode mudar com o tempo"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cuando-el-trueque-falla-scene","type":"story_scene","prompt_md":"Dessa vez não","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"neutral"},"payload":{"backdrop":"band","character":"dina","emotion":"neutral","action":"shake","body_md":"Na semana seguinte, Dino volta com mais peixes… mas Dina **já tem demais** cocos e não quer mais peixe. A troca da semana passada, dessa vez, não funciona.","art":{"icon":"sentiment_neutral","tint":"warning"}}},{"id":"cuando-el-trueque-falla-quiz","type":"quiz_mcq","prompt_md":"O que aconteceu dessa vez com a troca de Dino e Dina?","difficulty":1,"xp":10,"hints":["O que Dina disse sobre os cocos?"],"explanation_md":"A troca depende de que as duas pessoas queiram a troca NAQUELE MOMENTO, e isso pode mudar.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Dina não queria mais o que Dino oferecia"},{"id":"b","text_md":"Dino não tinha mais peixes","rationale_md":"Ele tinha sim, esse não era o problema."},{"id":"c","text_md":"Os cocos desapareceram","rationale_md":"Os cocos ainda estão lá, o problema é outro."}]}},{"id":"cuando-el-trueque-falla-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"O que as pessoas precisam muda. Por isso a troca nem sempre funciona do mesmo jeito.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"A troca sempre funciona do mesmo jeito, todas as semanas.","justifications":[{"id":"j1","text_md":"Verdade, o que funcionou uma vez funciona sempre."},{"id":"j2","text_md":"Falso, o que alguém precisa pode mudar com o tempo."},{"id":"j3","text_md":"Falso, porque a troca só pode ser feita uma vez na vida."}]}},{"id":"cuando-el-trueque-falla-pic","type":"picture_choice","prompt_md":"O que ajudaria mais Dino no futuro?","difficulty":1,"xp":20,"explanation_md":"Ter algo que quase todos sempre aceitam, como moedas, evita o problema de a troca nem sempre combinar.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Ter algo que quase todos sempre aceitam, como moedas"},{"id":"b","icon":"redo","label":"Oferecer os mesmos peixes de novo e de novo","rationale_md":"Isso não resolve o fato de não quererem mais."},{"id":"c","icon":"sentiment_very_dissatisfied","label":"Parar de trocar para sempre","rationale_md":"Desistir não resolve o problema."}]}}]}$j$::jsonb, $j${"cuando-el-trueque-falla-quiz":{"correct_option_id":"a"},"cuando-el-trueque-falla-tf":{"is_true":false,"correct_justification_id":"j2"},"cuando-el-trueque-falla-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lessons (id, topic_id, position, slug, title, difficulty, xp_total, estimated_minutes, "cast", status)
VALUES ('40400000-0000-0000-0000-000000000005', '40300000-0000-0000-0000-000000000003', 1, 'de-donde-vienen-las-monedas', $j${"en-US":"Where Coins Come From","es-MX":"De dónde vienen las monedas","pt-BR":"De onde vêm as moedas"}$j$::jsonb, 1, 40, 5, $j$["dina","dino"]$j$::jsonb, 'published')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000005', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"de-donde-vienen-las-monedas","title":"Where Coins Come From","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["Understand that money works because a community agrees to accept it"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"de-donde-vienen-las-monedas-scene","type":"story_scene","prompt_md":"Coins are born","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"surprised"},"payload":{"backdrop":"band","character":"dino","emotion":"surprised","action":"celebrate","body_md":"Tired of bartering not always working, the islanders get together. **They agree to use special shells** that everyone accepts as payment. The first coins are born!","art":{"icon":"emoji_events","tint":"delight"}}},{"id":"de-donde-vienen-las-monedas-quiz","type":"quiz_mcq","prompt_md":"Why did the archipelago start using special shells as coins?","difficulty":1,"xp":10,"hints":["Think about the problem they had with bartering."],"explanation_md":"Money works because EVERYONE trusts that others will accept it in exchange for things.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Because everyone agreed to accept them in exchange for things"},{"id":"b","text_md":"Because the shells are pretty","rationale_md":"Being pretty doesn't make something money — what matters is that everyone accepts it."},{"id":"c","text_md":"Because there were no more fish or coconuts","rationale_md":"There were still fish and coconuts — the problem was the bartering itself."}]}},{"id":"de-donde-vienen-las-monedas-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"That shared trust is what makes money work.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Coins work because everyone agrees to accept them.","justifications":[{"id":"j1","text_md":"True, that shared trust is what makes them work."},{"id":"j2","text_md":"False, coins only work if they're made of real gold."},{"id":"j3","text_md":"False, any object works as money even if nobody accepts it."}]}},{"id":"de-donde-vienen-las-monedas-pic","type":"picture_choice","prompt_md":"Which of these is the MOST important feature of a coin?","difficulty":1,"xp":20,"explanation_md":"What matters most about money is that the community trusts it and accepts it in exchange for things.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"handshake","label":"That people trust it and accept it"},{"id":"b","icon":"palette","label":"That it has a pretty color","rationale_md":"Color doesn't make it valid as money."},{"id":"c","icon":"straighten","label":"That it's very big","rationale_md":"Size doesn't determine its value as money."}]}}]}$j$::jsonb, $j${"de-donde-vienen-las-monedas-quiz":{"correct_option_id":"a"},"de-donde-vienen-las-monedas-tf":{"is_true":true,"correct_justification_id":"j1"},"de-donde-vienen-las-monedas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000005', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"de-donde-vienen-las-monedas","title":"De dónde vienen las monedas","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Comprender que el dinero funciona porque una comunidad acuerda aceptarlo"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"de-donde-vienen-las-monedas-scene","type":"story_scene","prompt_md":"Nacen las monedas","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"surprised"},"payload":{"backdrop":"band","character":"dino","emotion":"surprised","action":"celebrate","body_md":"Cansados de que el trueque no siempre funcione, los habitantes del archipiélago se reúnen. **Deciden usar conchas especiales** que todos aceptan como pago. ¡Nacen las primeras monedas!","art":{"icon":"emoji_events","tint":"delight"}}},{"id":"de-donde-vienen-las-monedas-quiz","type":"quiz_mcq","prompt_md":"¿Por qué el archipiélago empezó a usar conchas especiales como monedas?","difficulty":1,"xp":10,"hints":["Piensa en el problema que tenían con el trueque."],"explanation_md":"El dinero funciona porque TODOS confían en que otros lo van a aceptar a cambio de algo.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Porque todos estaban de acuerdo en aceptarlas a cambio de cosas"},{"id":"b","text_md":"Porque las conchas son bonitas","rationale_md":"Ser bonitas no las hace dinero, lo importante es que todos las acepten."},{"id":"c","text_md":"Porque ya no había pescados ni cocos","rationale_md":"Seguía habiendo pescados y cocos, el problema era el trueque."}]}},{"id":"de-donde-vienen-las-monedas-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"Esa confianza compartida es lo que hace funcionar al dinero.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Las monedas sirven porque todos están de acuerdo en aceptarlas.","justifications":[{"id":"j1","text_md":"Cierto, esa confianza compartida es lo que las hace funcionar."},{"id":"j2","text_md":"Falso, las monedas solo sirven si son de oro de verdad."},{"id":"j3","text_md":"Falso, cualquier objeto sirve como moneda aunque nadie lo acepte."}]}},{"id":"de-donde-vienen-las-monedas-pic","type":"picture_choice","prompt_md":"¿Cuál de estas es la característica MÁS importante de una moneda?","difficulty":1,"xp":20,"explanation_md":"Lo esencial del dinero es que la comunidad confíe en él y lo acepte a cambio de cosas.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"handshake","label":"Que la gente confíe en ella y la acepte"},{"id":"b","icon":"palette","label":"Que tenga un color bonito","rationale_md":"El color no la hace válida como dinero."},{"id":"c","icon":"straighten","label":"Que sea muy grande","rationale_md":"El tamaño no determina su valor como dinero."}]}}]}$j$::jsonb, $j${"de-donde-vienen-las-monedas-quiz":{"correct_option_id":"a"},"de-donde-vienen-las-monedas-tf":{"is_true":true,"correct_justification_id":"j1"},"de-donde-vienen-las-monedas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000005', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"de-donde-vienen-las-monedas","title":"De onde vêm as moedas","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Compreender que o dinheiro funciona porque uma comunidade concorda em aceitá-lo"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"de-donde-vienen-las-monedas-scene","type":"story_scene","prompt_md":"Nascem as moedas","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"surprised"},"payload":{"backdrop":"band","character":"dino","emotion":"surprised","action":"celebrate","body_md":"Cansados de a troca nem sempre funcionar, os moradores do arquipélago se reúnem. **Decidem usar conchas especiais** que todos aceitam como pagamento. Nascem as primeiras moedas!","art":{"icon":"emoji_events","tint":"delight"}}},{"id":"de-donde-vienen-las-monedas-quiz","type":"quiz_mcq","prompt_md":"Por que o arquipélago começou a usar conchas especiais como moedas?","difficulty":1,"xp":10,"hints":["Pense no problema que tinham com a troca."],"explanation_md":"O dinheiro funciona porque TODOS confiam que outros vão aceitá-lo em troca de algo.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Porque todos concordaram em aceitá-las em troca de coisas"},{"id":"b","text_md":"Porque as conchas são bonitas","rationale_md":"Ser bonita não faz algo virar dinheiro, o importante é todos aceitarem."},{"id":"c","text_md":"Porque não havia mais peixes nem cocos","rationale_md":"Ainda havia peixes e cocos, o problema era a troca em si."}]}},{"id":"de-donde-vienen-las-monedas-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"Essa confiança compartilhada é o que faz o dinheiro funcionar.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"As moedas funcionam porque todos concordam em aceitá-las.","justifications":[{"id":"j1","text_md":"Verdade, essa confiança compartilhada é o que as faz funcionar."},{"id":"j2","text_md":"Falso, as moedas só funcionam se forem de ouro de verdade."},{"id":"j3","text_md":"Falso, qualquer objeto funciona como moeda mesmo que ninguém aceite."}]}},{"id":"de-donde-vienen-las-monedas-pic","type":"picture_choice","prompt_md":"Qual destas é a característica MAIS importante de uma moeda?","difficulty":1,"xp":20,"explanation_md":"O essencial do dinheiro é que a comunidade confie nele e o aceite em troca de coisas.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"handshake","label":"Que as pessoas confiem nela e a aceitem"},{"id":"b","icon":"palette","label":"Que tenha uma cor bonita","rationale_md":"A cor não a torna válida como dinheiro."},{"id":"c","icon":"straighten","label":"Que seja bem grande","rationale_md":"O tamanho não determina seu valor como dinheiro."}]}}]}$j$::jsonb, $j${"de-donde-vienen-las-monedas-quiz":{"correct_option_id":"a"},"de-donde-vienen-las-monedas-tf":{"is_true":true,"correct_justification_id":"j1"},"de-donde-vienen-las-monedas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lessons (id, topic_id, position, slug, title, difficulty, xp_total, estimated_minutes, "cast", status)
VALUES ('40400000-0000-0000-0000-000000000006', '40300000-0000-0000-0000-000000000003', 2, 'cuidar-tu-dinero', $j${"en-US":"Taking Care of Your Money","es-MX":"Cuidar tu dinero","pt-BR":"Cuidar do seu dinheiro"}$j$::jsonb, 1, 40, 5, $j$["dina","dino"]$j$::jsonb, 'published')
