INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000006', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"cuidar-tu-dinero","title":"Taking Care of Your Money","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["Understand why keeping money in a safe place matters"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cuidar-tu-dinero-scene","type":"story_scene","prompt_md":"The first shell-coins","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"encouraging"},"payload":{"backdrop":"band","character":"dina","emotion":"encouraging","action":"point","body_md":"Dino gets his first shell-coins for helping to fish. **Dina gives him a little box** to keep them: \"This way they won't get lost or blown away\", she says.","art":{"icon":"inventory_2","tint":"primary"}}},{"id":"cuidar-tu-dinero-quiz","type":"quiz_mcq","prompt_md":"Why is it a good idea to keep your money in a safe place?","difficulty":1,"xp":10,"hints":["Think about what could happen to a coin dropped on the sand."],"explanation_md":"Keeping your money in a safe place stops it from getting lost, wet, or blown away.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"So it doesn't get lost or damaged"},{"id":"b","text_md":"So it multiplies by itself","rationale_md":"Keeping it safe doesn't multiply it — that comes later, from saving."},{"id":"c","text_md":"Because money can be eaten","rationale_md":"Money isn't food, it's for exchanging."}]}},{"id":"cuidar-tu-dinero-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"Taking care of your money means keeping it in a safe place so it doesn't get lost.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"It doesn't matter where you leave your coins, they'll always be there when you look for them.","justifications":[{"id":"j1","text_md":"True, coins never get lost."},{"id":"j2","text_md":"False, if you leave them lying around they can get lost, wet, or taken."},{"id":"j3","text_md":"False, because coins disappear on their own every night."}]}},{"id":"cuidar-tu-dinero-pic","type":"picture_choice","prompt_md":"What's the best place to keep your coins?","difficulty":1,"xp":20,"explanation_md":"A safe little box or piggy bank protects your coins from getting lost or damaged.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"savings","label":"A safe little box or piggy bank"},{"id":"b","icon":"waves","label":"Buried in the beach sand","rationale_md":"Sand and water can damage or lose them."},{"id":"c","icon":"air","label":"Loose in a torn pocket","rationale_md":"A torn pocket makes them easy to lose."}]}}]}$j$::jsonb, $j${"cuidar-tu-dinero-quiz":{"correct_option_id":"a"},"cuidar-tu-dinero-tf":{"is_true":false,"correct_justification_id":"j2"},"cuidar-tu-dinero-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000006', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"cuidar-tu-dinero","title":"Cuidar tu dinero","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Comprender por qué es importante guardar el dinero en un lugar seguro"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cuidar-tu-dinero-scene","type":"story_scene","prompt_md":"Las primeras conchas-moneda","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"encouraging"},"payload":{"backdrop":"band","character":"dina","emotion":"encouraging","action":"point","body_md":"Dino recibe sus primeras conchas-moneda por ayudar a pescar. **Dina le regala una cajita** para guardarlas: 'Así no se te pierden ni se las lleva el viento', le dice.","art":{"icon":"inventory_2","tint":"primary"}}},{"id":"cuidar-tu-dinero-quiz","type":"quiz_mcq","prompt_md":"¿Por qué es buena idea guardar tu dinero en un lugar seguro?","difficulty":1,"xp":10,"hints":["Piensa qué le podría pasar a una moneda tirada en la arena."],"explanation_md":"Guardar tu dinero en un lugar seguro evita que se pierda, se moje o se lo lleve el viento.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Para que no se pierda ni se dañe"},{"id":"b","text_md":"Para que se multiplique solo","rationale_md":"Guardarlo no lo multiplica, eso vendrá después con el ahorro."},{"id":"c","text_md":"Porque el dinero se puede comer","rationale_md":"El dinero no se come, es para intercambiar."}]}},{"id":"cuidar-tu-dinero-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"Cuidar tu dinero significa guardarlo en un lugar seguro para que no se pierda.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"No importa dónde dejes tus monedas, siempre estarán ahí cuando las busques.","justifications":[{"id":"j1","text_md":"Cierto, las monedas nunca se pierden."},{"id":"j2","text_md":"Falso, si las dejas tiradas se pueden perder, mojar o alguien más las puede tomar."},{"id":"j3","text_md":"Falso, porque las monedas desaparecen solas cada noche."}]}},{"id":"cuidar-tu-dinero-pic","type":"picture_choice","prompt_md":"¿Cuál es el mejor lugar para guardar tus monedas?","difficulty":1,"xp":20,"explanation_md":"Una alcancía o cajita segura protege tus monedas de perderse o dañarse.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"savings","label":"Una cajita o alcancía segura"},{"id":"b","icon":"waves","label":"Enterradas en la arena de la playa","rationale_md":"La arena y el agua pueden dañarlas o perderlas."},{"id":"c","icon":"air","label":"Sueltas en tu bolsillo roto","rationale_md":"Un bolsillo roto hace fácil que las pierdas."}]}}]}$j$::jsonb, $j${"cuidar-tu-dinero-quiz":{"correct_option_id":"a"},"cuidar-tu-dinero-tf":{"is_true":false,"correct_justification_id":"j2"},"cuidar-tu-dinero-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000006', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"cuidar-tu-dinero","title":"Cuidar do seu dinheiro","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Compreender por que é importante guardar o dinheiro em um lugar seguro"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"cuidar-tu-dinero-scene","type":"story_scene","prompt_md":"As primeiras conchas-moeda","difficulty":1,"xp":0,"narrator":{"character":"dina","emotion":"encouraging"},"payload":{"backdrop":"band","character":"dina","emotion":"encouraging","action":"point","body_md":"Dino recebe suas primeiras conchas-moeda por ajudar a pescar. **Dina lhe dá uma caixinha** para guardá-las: \"Assim elas não se perdem nem voam com o vento\", ela diz.","art":{"icon":"inventory_2","tint":"primary"}}},{"id":"cuidar-tu-dinero-quiz","type":"quiz_mcq","prompt_md":"Por que é boa ideia guardar seu dinheiro em um lugar seguro?","difficulty":1,"xp":10,"hints":["Pense no que pode acontecer com uma moeda jogada na areia."],"explanation_md":"Guardar seu dinheiro em um lugar seguro evita que ele se perca, se molhe ou voe com o vento.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Para que não se perca nem se estrague"},{"id":"b","text_md":"Para que se multiplique sozinho","rationale_md":"Guardá-lo não o multiplica, isso vem depois com a poupança."},{"id":"c","text_md":"Porque o dinheiro pode ser comido","rationale_md":"Dinheiro não se come, é para trocar."}]}},{"id":"cuidar-tu-dinero-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"Cuidar do seu dinheiro significa guardá-lo em um lugar seguro para não se perder.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Não importa onde você deixe suas moedas, elas sempre estarão lá quando você procurar.","justifications":[{"id":"j1","text_md":"Verdade, as moedas nunca se perdem."},{"id":"j2","text_md":"Falso, se você as deixar largadas elas podem se perder, molhar ou alguém pode pegá-las."},{"id":"j3","text_md":"Falso, porque as moedas desaparecem sozinhas toda noite."}]}},{"id":"cuidar-tu-dinero-pic","type":"picture_choice","prompt_md":"Qual é o melhor lugar para guardar suas moedas?","difficulty":1,"xp":20,"explanation_md":"Um cofrinho ou caixinha segura protege suas moedas de se perderem ou estragarem.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"savings","label":"Uma caixinha ou cofrinho seguro"},{"id":"b","icon":"waves","label":"Enterradas na areia da praia","rationale_md":"A areia e a água podem estragá-las ou perdê-las."},{"id":"c","icon":"air","label":"Soltas em um bolso rasgado","rationale_md":"Um bolso rasgado facilita perdê-las."}]}}]}$j$::jsonb, $j${"cuidar-tu-dinero-quiz":{"correct_option_id":"a"},"cuidar-tu-dinero-tf":{"is_true":false,"correct_justification_id":"j2"},"cuidar-tu-dinero-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lessons (id, topic_id, position, slug, title, difficulty, xp_total, estimated_minutes, "cast", status)
VALUES ('40400000-0000-0000-0000-000000000007', '40300000-0000-0000-0000-000000000004', 1, 'comprar-lo-que-necesitas', $j${"en-US":"Buying What You Need","es-MX":"Comprar lo que necesitas","pt-BR":"Comprar o que você precisa"}$j$::jsonb, 1, 40, 5, $j$["dina","dino"]$j$::jsonb, 'published')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000007', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"comprar-lo-que-necesitas","title":"Buying What You Need","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["Understand how coins make buying easier than bartering"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"comprar-lo-que-necesitas-scene","type":"story_scene","prompt_md":"First time paying","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"happy"},"payload":{"backdrop":"band","character":"dino","emotion":"happy","action":"nod","body_md":"Dino is hungry. Instead of looking for someone who wants to trade for food, **he walks to the fruit stall and pays with his coins**. He gets his mango with no trouble at all!","art":{"icon":"shopping_basket","tint":"success"}}},{"id":"comprar-lo-que-necesitas-quiz","type":"quiz_mcq","prompt_md":"What made things easier for Dino by using coins?","difficulty":1,"xp":10,"hints":["Compare this with the bartering problem from before."],"explanation_md":"With coins, you no longer need the other person to want exactly what you offer: you just need them to accept your money.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"He no longer needs to find someone who wants exactly what he has"},{"id":"b","text_md":"He no longer needs to eat","rationale_md":"Dino still needs to eat, only how he gets food changed."},{"id":"c","text_md":"Fruit is now free","rationale_md":"Dino still pays, just with coins now."}]}},{"id":"comprar-lo-que-necesitas-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"Coins simplify exchanges because almost everyone accepts them, unlike bartering.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Buying with coins is easier than bartering because almost everyone accepts coins.","justifications":[{"id":"j1","text_md":"True, that's why money solved the bartering problem."},{"id":"j2","text_md":"False, buying with coins is harder than bartering."},{"id":"j3","text_md":"False, because coins can't be used to buy food."}]}},{"id":"comprar-lo-que-necesitas-pic","type":"picture_choice","prompt_md":"What does Dino need to buy his mango?","difficulty":1,"xp":20,"explanation_md":"Buying with coins only requires having enough money for the price asked.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Enough coins to pay the price"},{"id":"b","icon":"search","label":"Find someone who wants exactly what he has","rationale_md":"That was needed for bartering, not for buying with coins."},{"id":"c","icon":"card_giftcard","label":"Wait for it to be given to him for free","rationale_md":"Buying means paying, not waiting for a gift."}]}}]}$j$::jsonb, $j${"comprar-lo-que-necesitas-quiz":{"correct_option_id":"a"},"comprar-lo-que-necesitas-tf":{"is_true":true,"correct_justification_id":"j1"},"comprar-lo-que-necesitas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000007', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"comprar-lo-que-necesitas","title":"Comprar lo que necesitas","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Comprender cómo las monedas hacen más fácil comprar que el trueque"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"comprar-lo-que-necesitas-scene","type":"story_scene","prompt_md":"La primera vez que paga","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"happy"},"payload":{"backdrop":"band","character":"dino","emotion":"happy","action":"nod","body_md":"Dino tiene hambre. En vez de buscar a alguien que quiera cambiar cosas por comida, **camina al puesto de frutas y paga con sus monedas**. ¡Consigue su mango sin complicaciones!","art":{"icon":"shopping_basket","tint":"success"}}},{"id":"comprar-lo-que-necesitas-quiz","type":"quiz_mcq","prompt_md":"¿Qué hizo más fácil el uso de monedas para Dino?","difficulty":1,"xp":10,"hints":["Compara esto con el problema del trueque de antes."],"explanation_md":"Con monedas, ya no necesitas que la otra persona quiera justo lo que tú ofreces: solo necesitas que acepte tu dinero.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Ya no necesita encontrar a alguien que quiera justo lo que él tiene"},{"id":"b","text_md":"Ya no necesita comer","rationale_md":"Dino sigue necesitando comer, solo cambió cómo lo consigue."},{"id":"c","text_md":"Las frutas ahora son gratis","rationale_md":"Dino sigue pagando, solo que con monedas."}]}},{"id":"comprar-lo-que-necesitas-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"Las monedas simplifican los intercambios porque casi todos las aceptan, a diferencia del trueque.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Comprar con monedas es más fácil que el trueque porque casi todos aceptan las monedas.","justifications":[{"id":"j1","text_md":"Cierto, por eso el dinero resolvió el problema del trueque."},{"id":"j2","text_md":"Falso, comprar con monedas es más difícil que el trueque."},{"id":"j3","text_md":"Falso, porque las monedas no sirven para comprar comida."}]}},{"id":"comprar-lo-que-necesitas-pic","type":"picture_choice","prompt_md":"¿Qué necesita Dino para comprar su mango?","difficulty":1,"xp":20,"explanation_md":"Comprar con monedas solo requiere tener suficiente dinero para el precio pedido.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Suficientes monedas para pagar el precio"},{"id":"b","icon":"search","label":"Encontrar a alguien que quiera exactamente lo que él tiene","rationale_md":"Eso era necesario en el trueque, ya no con monedas."},{"id":"c","icon":"card_giftcard","label":"Esperar a que se lo regalen","rationale_md":"Comprar significa pagar, no esperar un regalo."}]}}]}$j$::jsonb, $j${"comprar-lo-que-necesitas-quiz":{"correct_option_id":"a"},"comprar-lo-que-necesitas-tf":{"is_true":true,"correct_justification_id":"j1"},"comprar-lo-que-necesitas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000007', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"comprar-lo-que-necesitas","title":"Comprar o que você precisa","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Compreender como as moedas tornam comprar mais fácil que a troca"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"comprar-lo-que-necesitas-scene","type":"story_scene","prompt_md":"A primeira vez que paga","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"happy"},"payload":{"backdrop":"band","character":"dino","emotion":"happy","action":"nod","body_md":"Dino está com fome. Em vez de procurar alguém que queira trocar coisas por comida, **ele vai até a barraca de frutas e paga com suas moedas**. Ele consegue sua manga sem complicação!","art":{"icon":"shopping_basket","tint":"success"}}},{"id":"comprar-lo-que-necesitas-quiz","type":"quiz_mcq","prompt_md":"O que tornou as coisas mais fáceis para Dino ao usar moedas?","difficulty":1,"xp":10,"hints":["Compare isso com o problema da troca de antes."],"explanation_md":"Com moedas, você não precisa mais que a outra pessoa queira exatamente o que você oferece: só precisa que ela aceite seu dinheiro.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Ele não precisa mais achar alguém que queira exatamente o que ele tem"},{"id":"b","text_md":"Ele não precisa mais comer","rationale_md":"Dino ainda precisa comer, só mudou como ele consegue."},{"id":"c","text_md":"As frutas agora são grátis","rationale_md":"Dino continua pagando, só que com moedas."}]}},{"id":"comprar-lo-que-necesitas-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"As moedas simplificam as trocas porque quase todos as aceitam, ao contrário da troca direta.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Comprar com moedas é mais fácil que a troca porque quase todos aceitam moedas.","justifications":[{"id":"j1","text_md":"Verdade, por isso o dinheiro resolveu o problema da troca."},{"id":"j2","text_md":"Falso, comprar com moedas é mais difícil que a troca."},{"id":"j3","text_md":"Falso, porque moedas não servem para comprar comida."}]}},{"id":"comprar-lo-que-necesitas-pic","type":"picture_choice","prompt_md":"O que Dino precisa para comprar sua manga?","difficulty":1,"xp":20,"explanation_md":"Comprar com moedas só exige ter dinheiro suficiente para o preço pedido.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"paid","label":"Moedas suficientes para pagar o preço"},{"id":"b","icon":"search","label":"Achar alguém que queira exatamente o que ele tem","rationale_md":"Isso era necessário na troca, já não com moedas."},{"id":"c","icon":"card_giftcard","label":"Esperar que dêem de graça","rationale_md":"Comprar significa pagar, não esperar um presente."}]}}]}$j$::jsonb, $j${"comprar-lo-que-necesitas-quiz":{"correct_option_id":"a"},"comprar-lo-que-necesitas-tf":{"is_true":true,"correct_justification_id":"j1"},"comprar-lo-que-necesitas-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

