VALUES ('40400000-0000-0000-0000-000000000008', '40300000-0000-0000-0000-000000000004', 2, 'ahorrar-para-manana', $j${"en-US":"Saving for Tomorrow","es-MX":"Ahorrar para mañana","pt-BR":"Poupar para amanhã"}$j$::jsonb, 1, 40, 5, $j$["dina","dino"]$j$::jsonb, 'published')
