INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000008', 'en-US', 1, $j${"schema_version":1,"meta":{"slug":"ahorrar-para-manana","title":"Saving for Tomorrow","locale":"en-US","subject":"money","estimated_minutes":5,"objectives":["Understand saving as keeping part of your money for later"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"ahorrar-para-manana-scene","type":"story_scene","prompt_md":"A bigger dream","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"thinking"},"payload":{"backdrop":"band","character":"dino","emotion":"thinking","action":"think","body_md":"Dino already has his boat, but he dreams of an **even bigger one**. Dina suggests: \"Don't spend all your coins today. Save a little each week and soon you'll have enough.\"","art":{"icon":"savings","tint":"accent"}}},{"id":"ahorrar-para-manana-quiz","type":"quiz_mcq","prompt_md":"What does Dina suggest so Dino can get the bigger boat?","difficulty":1,"xp":10,"hints":["What does it mean to NOT spend everything at once?"],"explanation_md":"Saving means keeping part of your money today so you can use it for something later.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Save a bit of his coins every week"},{"id":"b","text_md":"Spend everything he has right now","rationale_md":"Spending it all doesn't help him save up for later."},{"id":"c","text_md":"Borrow from everyone on the island","rationale_md":"Dina isn't suggesting borrowing, but saving."}]}},{"id":"ahorrar-para-manana-tf","type":"true_false","prompt_md":"Dina says something. Is it true?","difficulty":1,"xp":10,"explanation_md":"Saving is keeping part of your money today so you have more options tomorrow.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Saving means spending all your coins as soon as you get them.","justifications":[{"id":"j1","text_md":"True, saving is spending fast."},{"id":"j2","text_md":"False, saving is keeping part of your money to use later."},{"id":"j3","text_md":"False, because saving means giving your coins away."}]}},{"id":"ahorrar-para-manana-pic","type":"picture_choice","prompt_md":"Which of these is a good saving habit?","difficulty":1,"xp":20,"explanation_md":"Regularly setting aside part of your coins is the base of good saving.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"savings","label":"Saving a few coins every week in the piggy bank"},{"id":"b","icon":"bolt","label":"Spending it all the same day you get it","rationale_md":"That leaves nothing saved for later."},{"id":"c","icon":"help","label":"Forgetting where you kept your coins","rationale_md":"That isn't saving, that's losing your money."}]}}]}$j$::jsonb, $j${"ahorrar-para-manana-quiz":{"correct_option_id":"a"},"ahorrar-para-manana-tf":{"is_true":false,"correct_justification_id":"j2"},"ahorrar-para-manana-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000008', 'es-MX', 1, $j${"schema_version":1,"meta":{"slug":"ahorrar-para-manana","title":"Ahorrar para mañana","locale":"es-MX","subject":"money","estimated_minutes":5,"objectives":["Comprender el ahorro como guardar parte de tu dinero para después"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"ahorrar-para-manana-scene","type":"story_scene","prompt_md":"Un sueño más grande","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"thinking"},"payload":{"backdrop":"band","character":"dino","emotion":"thinking","action":"think","body_md":"Dino ya tiene su barquito, pero sueña con uno **todavía más grande**. Dina le sugiere: 'No gastes todas tus monedas hoy. Guarda un poco cada semana y pronto tendrás suficiente'.","art":{"icon":"savings","tint":"accent"}}},{"id":"ahorrar-para-manana-quiz","type":"quiz_mcq","prompt_md":"¿Qué le sugiere Dina a Dino para conseguir el barquito más grande?","difficulty":1,"xp":10,"hints":["¿Qué significa NO gastar todo de una vez?"],"explanation_md":"Ahorrar significa guardar una parte de tu dinero hoy para poder usarlo en algo más adelante.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Guardar un poco de sus monedas cada semana"},{"id":"b","text_md":"Gastar todo lo que tiene ahora mismo","rationale_md":"Gastar todo no le ayuda a juntar más para después."},{"id":"c","text_md":"Pedirle prestado a todos en la isla","rationale_md":"Dina no sugiere pedir prestado, sino ahorrar."}]}},{"id":"ahorrar-para-manana-tf","type":"true_false","prompt_md":"Dina dice una frase. ¿Es cierta?","difficulty":1,"xp":10,"explanation_md":"Ahorrar es guardar una parte de tu dinero hoy para tener más opciones mañana.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Ahorrar significa gastar todas tus monedas apenas las consigues.","justifications":[{"id":"j1","text_md":"Cierto, ahorrar es gastar rápido."},{"id":"j2","text_md":"Falso, ahorrar es guardar una parte de tu dinero para usarla después."},{"id":"j3","text_md":"Falso, porque ahorrar significa regalar tus monedas."}]}},{"id":"ahorrar-para-manana-pic","type":"picture_choice","prompt_md":"¿Cuál de estos es un buen hábito de ahorro?","difficulty":1,"xp":20,"explanation_md":"Guardar una parte de tus monedas regularmente es la base del buen ahorro.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"savings","label":"Guardar unas monedas cada semana en la alcancía"},{"id":"b","icon":"bolt","label":"Gastar todo el mismo día que lo recibes","rationale_md":"Eso no deja nada guardado para después."},{"id":"c","icon":"help","label":"Olvidar dónde guardaste tus monedas","rationale_md":"Eso no es ahorrar, es perder tu dinero."}]}}]}$j$::jsonb, $j${"ahorrar-para-manana-quiz":{"correct_option_id":"a"},"ahorrar-para-manana-tf":{"is_true":false,"correct_justification_id":"j2"},"ahorrar-para-manana-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;

INSERT INTO public.lesson_documents (lesson_id, locale, schema_version, document, answer_keys, audio)
VALUES ('40400000-0000-0000-0000-000000000008', 'pt-BR', 1, $j${"schema_version":1,"meta":{"slug":"ahorrar-para-manana","title":"Poupar para amanhã","locale":"pt-BR","subject":"money","estimated_minutes":5,"objectives":["Compreender a poupança como guardar parte do seu dinheiro para depois"],"cast":["dina","dino"]},"scoring":{"pass_threshold":70,"hint_penalty_pct":10,"max_attempts":2,"hearts":null},"segments":[{"id":"ahorrar-para-manana-scene","type":"story_scene","prompt_md":"Um sonho maior","difficulty":1,"xp":0,"narrator":{"character":"dino","emotion":"thinking"},"payload":{"backdrop":"band","character":"dino","emotion":"thinking","action":"think","body_md":"Dino já tem seu barquinho, mas sonha com um **ainda maior**. Dina sugere: \"Não gaste todas as suas moedas hoje. Guarde um pouco a cada semana e logo terá o suficiente.\"","art":{"icon":"savings","tint":"accent"}}},{"id":"ahorrar-para-manana-quiz","type":"quiz_mcq","prompt_md":"O que Dina sugere para Dino conseguir o barquinho maior?","difficulty":1,"xp":10,"hints":["O que significa NÃO gastar tudo de uma vez?"],"explanation_md":"Poupar significa guardar uma parte do seu dinheiro hoje para poder usá-lo em algo mais tarde.","narrator":{"character":"dina","emotion":"happy"},"payload":{"options":[{"id":"a","text_md":"Guardar um pouco de suas moedas toda semana"},{"id":"b","text_md":"Gastar tudo o que tem agora mesmo","rationale_md":"Gastar tudo não ajuda a juntar mais para depois."},{"id":"c","text_md":"Pedir emprestado a todos na ilha","rationale_md":"Dina não sugere pedir emprestado, e sim poupar."}]}},{"id":"ahorrar-para-manana-tf","type":"true_false","prompt_md":"Dina diz uma frase. É verdade?","difficulty":1,"xp":10,"explanation_md":"Poupar é guardar uma parte do seu dinheiro hoje para ter mais opções amanhã.","narrator":{"character":"dina","emotion":"thinking"},"payload":{"statement_md":"Poupar significa gastar todas as suas moedas assim que as recebe.","justifications":[{"id":"j1","text_md":"Verdade, poupar é gastar rápido."},{"id":"j2","text_md":"Falso, poupar é guardar uma parte do seu dinheiro para usar depois."},{"id":"j3","text_md":"Falso, porque poupar significa dar suas moedas de presente."}]}},{"id":"ahorrar-para-manana-pic","type":"picture_choice","prompt_md":"Qual destes é um bom hábito de poupança?","difficulty":1,"xp":20,"explanation_md":"Guardar regularmente uma parte das suas moedas é a base de uma boa poupança.","narrator":{"character":"dino","emotion":"thinking"},"payload":{"options":[{"id":"a","icon":"savings","label":"Guardar algumas moedas toda semana no cofrinho"},{"id":"b","icon":"bolt","label":"Gastar tudo no mesmo dia em que recebe","rationale_md":"Isso não deixa nada guardado para depois."},{"id":"c","icon":"help","label":"Esquecer onde guardou suas moedas","rationale_md":"Isso não é poupar, é perder seu dinheiro."}]}}]}$j$::jsonb, $j${"ahorrar-para-manana-quiz":{"correct_option_id":"a"},"ahorrar-para-manana-tf":{"is_true":false,"correct_justification_id":"j2"},"ahorrar-para-manana-pic":{"correct_option_id":"a"}}$j$::jsonb, '{}'::jsonb)
ON CONFLICT (lesson_id, locale) DO NOTHING;
